```ts
type EnforcementEvent =
  | { type: "opened";    caseId; data: { findingKey; sendingDomainId: string | null; reason: OpenReason; severity; evidence } }
  | { type: "upheld";    caseId; data: {} }
  | { type: "released";  caseId; data: { reason: "review.wrong" | "review.fixed" | "review.released" } }
  | { type: "commented"; caseId; data: {} }
  | { type: "review_requested"; caseId; data: {} }   // Pending on an upheld case: back in the queue
  // later: claimed, allowed, narrowed, escalated, proposed …
  & { teamId; version; at; actorUserId?: string; actorRule?: string; note?: string };

function apply(s: TeamState, e: EnforcementEvent): TeamState {
  switch (e.type) {
    case "opened":    return addCase(s, e);
    case "upheld":    return markReviewed(s, e);
    case "released":  return close(s, e);
    case "commented": return addNote(s, e);
    default:          return assertNever(e);
  }
}
```

- `apply` validates nothing and reads no clock, database or evidence. Validation happens before an event is written.
- `disabled(domain)` = some open case targets the domain, or the whole team.
- Queue row = open cases not yet upheld, grouped by team: `max(severityRank)`, oldest `openedAt`.
